+++ b/internal/hosted/eval/harness.go
@@ -0,0 +1,105 @@
+package eval
+
+import (
+	"context"
+	"errors"
+	"fmt"
+	"sort"
+	"time"
+)
+
+type Finding struct {
+	Path, Severity     string
+	StartLine, EndLine int
+}
+type ReviewResult struct {
+	Findings     []Finding
+	CostMicrousd int64
+	Latency      time.Duration
+}
+type Reviewer interface {
+	Review(context.Context, Case) (ReviewResult, error)
+}
+type Metrics struct {
+	Precision, Recall float64
+	CostMicrousd      int64
+	MedianLatency     time.Duration
+	Cases             int
+}
+
+func Run(ctx context.Context, dataset Dataset, reviewer Reviewer) (Metrics, error) {
+	if reviewer == nil {
+		return Metrics{}, errors.New("reviewer is required")
+	}
+	if err := dataset.Validate(); err != nil {
+		return Metrics{}, err
+	}
+	var matchedFindings, totalFindings, matchedLabels, totalLabels int
+	var totalCost int64
+	latencies := make([]time.Duration, 0, len(dataset.Cases))
+	for _, benchmark := range dataset.Cases {
+		result, err := reviewer.Review(ctx, benchmark)
+		if err != nil {
+			return Metrics{}, fmt.Errorf("review case %s: %w", benchmark.ID, err)
+		}
+		totalCost += result.CostMicrousd
+		latencies = append(latencies, result.Latency)
+		totalFindings += len(result.Findings)
+		totalLabels += len(benchmark.Labels)
+		for _, finding := range result.Findings {
+			if matchesAny(finding, benchmark.Labels) {
+				matchedFindings++
+			}
+		}
+		for _, label := range benchmark.Labels {
+			if labelMatched(label, result.Findings) {
+				matchedLabels++
+			}
+		}
+	}
+	sort.Slice(latencies, func(i, j int) bool { return latencies[i] < latencies[j] })
+	metrics := Metrics{CostMicrousd: totalCost, Cases: len(dataset.Cases)}
+	if totalFindings > 0 {
+		metrics.Precision = float64(matchedFindings) / float64(totalFindings)
+	}
+	if totalLabels > 0 {
+		metrics.Recall = float64(matchedLabels) / float64(totalLabels)
+	}
+	if len(latencies) > 0 {
+		metrics.MedianLatency = latencies[len(latencies)/2]
+	}
+	return metrics, nil
+}
+
+func GateRegression(current, baseline Metrics, maxDrop float64) error {
+	if maxDrop <= 0 {
+		maxDrop = .03
+	}
+	if baseline.Precision-current.Precision > maxDrop {
+		return fmt.Errorf("precision regressed %.1f points", (baseline.Precision-current.Precision)*100)
+	}
+	if baseline.Recall-current.Recall > maxDrop {
+		return fmt.Errorf("recall regressed %.1f points", (baseline.Recall-current.Recall)*100)
+	}
+	return nil
+}
+
+func matchesAny(f Finding, labels []Label) bool {
+	for _, l := range labels {
+		if overlap(f, l) {
+			return true
+		}
+	}
+	return false
+}
+func labelMatched(l Label, findings []Finding) bool {
+	for _, f := range findings {
+		if overlap(f, l) {
+			return true
+		}
+	}
+	return false
+}
+func overlap(f Finding, l Label) bool {
+	return f.Path == l.Path && f.StartLine <= l.EndLine && l.StartLine <= f.EndLine
+}

diff --git a/internal/hosted/eval/harness_test.go b/internal/hosted/eval/harness_test.go
new file mode 100644
index 0000000..9424190
--- /dev/null
+++ b/internal/hosted/eval/harness_test.go
@@ -0,0 +1,38 @@
+package eval
+
+import (
+	"context"
+	"strings"
+	"testing"
+	"time"
+)
+
+type reviewerFunc func(context.Context, Case) (ReviewResult, error)
+
+func (f reviewerFunc) Review(ctx context.Context, c Case) (ReviewResult, error) { return f(ctx, c) }
+
+func TestRunMeasuresPrecisionRecallCostAndMedianLatency(t *testing.T) {
+	cases := []Case{}
+	for i := 0; i < 3; i++ {
+		cases = append(cases, Case{ID: string(rune('a' + i)), Kind: "seeded", Repository: "https://github.com/acme/repo", PullRequestURL: "https://github.com/acme/repo/pull/1", BaseSHA: strings.Repeat("a", 40), HeadSHA: strings.Repeat("b", 40), MutationID: "m", Labels: []Label{{Path: "a.go", BugClass: "logic", StartLine: 5, EndLine: 5}}})
+	}
+	metrics, err := Run(context.Background(), Dataset{Version: 1, Cases: cases}, reviewerFunc(func(_ context.Context, c Case) (ReviewResult, error) {
+		return ReviewResult{Findings: []Finding{{Path: "a.go", StartLine: 5, EndLine: 5}, {Path: "b.go", StartLine: 1, EndLine: 1}}, CostMicrousd: 10, Latency: time.Duration(c.ID[0]-'a'+1) * time.Second}, nil
+	}))
+	if err != nil {
+		t.Fatal(err)
+	}
+	if metrics.Precision != .5 || metrics.Recall != 1 || metrics.CostMicrousd != 30 || metrics.MedianLatency != 2*time.Second {
+		t.Fatalf("metrics = %#v", metrics)
+	}
+}
+
+func TestGateRegressionBlocksThreePointQualityDrop(t *testing.T) {
+	baseline := Metrics{Precision: .8, Recall: .7}
+	if GateRegression(Metrics{Precision: .78, Recall: .68}, baseline, .03) != nil {
+		t.Fatal("blocked acceptable change")
+	}
+	if GateRegression(Metrics{Precision: .75, Recall: .7}, baseline, .03) == nil {
+		t.Fatal("accepted precision regression")
+	}
+}
